const items = $input.all();

return items.map(item => {
  let text = $('AI Agent').first().json.output || item.json.output || '';

  // Change ** to *
  text = text.replace(/\*\*(.+?)\*\*/g, '*$1*');
  // Change header### to *title*
  text = text.replace(/^#{1,6}\s+(.+)$/gm, '*$1*');
  // Delete line --- or ___
  text = text.replace(/^\s*[-_]{3,}\s*$/gm, '');
  // Change Sub-Title to *Sub-Title* with space before
  text = text.replace(/^\s*-?\s*\*([^*\n]+?):?\*\s*:?\s*$/gm, '\n\n*$1:*');

  // Give space after title
  text = text.replace(/^(\*[^*\n]+\*)\n(?=\d+\.|- )/gm, '$1\n\n');
  // Organize the list of subpoints
  text = text.replace(/^\s*[•·–-]\s+/gm, '- ');
  // Delete Space after number
  text = text.replace(/^\s*(\d+\.)\s+/gm, '$1 ');
  // Make sure only one row space
  text = text.replace(/\n{3,}/g, '\n\n').trim();

  return {
    json: {
      ...item.json,
      clean_text: text
    }
  };
});
